# Generated by joobqui-selfhosted sdk:generate from templates/sdks/elixir/test/joobq/error_test.exs.j2. DO NOT EDIT.
defmodule JoobQ.ErrorTest do
  use ExUnit.Case, async: true

  alias JoobQ.Error

  # The registry's docs address, spelled in two parts (the template guard allows only the SDK codes' URLs whole).
  @docs "https://joobq.io/errors/"

  test "a gateway code that is not text, or holds line breaks, never breaks a message or a log line" do
    assert %Error{code: "http_422"} = error = Error.from_response(422, envelope(%{"nested" => 1}))
    assert Exception.message(error) =~ "(422 http_422)"
    assert %Error{code: "bad code here"} = Error.from_response(422, envelope("bad\ncode\r\nhere"))
    assert Exception.message(%Error{status: 409, code: 7, message: "m"}) =~ "(409 http_409)"
    refute Exception.message(%Error{status: nil, code: "a\nb", message: "m"}) =~ "\n"
  end

  defp envelope(code), do: %{"error" => %{"code" => code, "message" => "m", "request_id" => "r1"}}

  test "reads the gateway's error envelope" do
    error =
      Error.from_response(422, %{
        "error" => %{"code" => "invalid", "message" => "bad", "details" => ["x"]}
      })

    assert %Error{reason: :invalid, status: 422, code: "invalid", message: "bad", details: ["x"]} =
             error
  end

  test "maps 402 pro_required to its own reason" do
    assert %Error{reason: :pro_required, request_id: "r1"} =
             Error.from_response(402, envelope("pro_required"))

    assert %Error{reason: :gateway} = Error.from_response(402, envelope("payment"))
  end

  test "maps the other statuses" do
    assert %Error{reason: :unauthorized} =
             Error.from_response(401, envelope("sdk_token_required"))

    assert %Error{reason: :unavailable} =
             Error.from_response(503, envelope("sdk_token_not_configured"))

    assert %Error{reason: :gateway, code: "http_404", message: "nope"} =
             Error.from_response(404, "nope")
  end

  test "cuts the gateway's message to 300 characters, envelope or not" do
    long = String.duplicate("x", 1_000)
    envelope = %{"error" => %{"code" => "invalid", "message" => long}}
    assert String.length(Error.from_response(422, envelope).message) == 300
    assert String.length(Error.from_response(500, long).message) == 300
    assert Error.from_response(422, %{"error" => %{"message" => 7}}).message == ""
  end

  defp coded(jq_code),
    do: %{
      "error" => %{
        "code" => "unauthenticated",
        "jq_code" => jq_code,
        "docs_url" => "https://evil.example/x",
        "message" => "wrong\u0007 token\n\n here",
        "request_id" => "r1"
      }
    }

  test "a registry code is kept, its docs URL built by the SDK, and the message ends with both once" do
    error = Error.from_response(401, coded("JQ-801"))

    assert %Error{
             reason: :unauthorized,
             code: "unauthenticated",
             jq_code: "JQ-801"
           } = error

    assert error.docs_url == @docs <> "JQ-801"

    assert Exception.message(error) ==
             "JoobQ gateway error (401 unauthenticated): wrong token here [JQ-801] " <>
               @docs <> "JQ-801"

    assert %Error{jq_code: "JQ-8000"} = Error.from_response(422, coded("JQ-8000"))
  end

  test "a server message that already ends with the registry suffix gets it once" do
    suffix = " [JQ-801] " <> @docs <> "JQ-801"

    error =
      Error.from_response(401, %{
        "error" => %{
          "code" => "unauthenticated",
          "jq_code" => "JQ-801",
          "message" => "no" <> suffix
        }
      })

    assert Exception.message(error) == "JoobQ gateway error (401 unauthenticated): no" <> suffix
  end

  test "a registry code with no message and no code leaves no double space" do
    error = Error.from_response(401, %{"error" => %{"jq_code" => "JQ-801"}})

    assert Exception.message(error) ==
             "JoobQ gateway error (401 http_401): [JQ-801] " <> @docs <> "JQ-801"

    refute Exception.message(error) =~ "  "
  end

  test "without a well-formed registry code, an error is what it was" do
    plain =
      Error.from_response(401, %{"error" => %{"code" => "unauthenticated", "message" => "m"}})

    assert %Error{jq_code: nil, docs_url: nil} = plain
    assert Exception.message(plain) == "JoobQ gateway error (401 unauthenticated): m"

    for bad <- [
          "javascript:alert(1)",
          "JQ-1",
          "1234567890",
          "JQ-12345",
          "JQ-801\n",
          "jq-801",
          801,
          ["JQ-801"]
        ] do
      error = Error.from_response(401, coded(bad))
      assert %Error{jq_code: nil, docs_url: nil} = error
      refute Exception.message(error) =~ "joobq.io"
    end

    assert %Error{jq_code: nil} = Error.from_response(500, "not json")
    assert %Error{jq_code: nil} = Error.from_response(302, coded("JQ-801"))
  end

  test "a 2xx answer that is not JSON says the job may be stored" do
    error = Error.bad_response(201)
    assert %Error{reason: :bad_response, status: 201} = error
    assert Exception.message(error) =~ "may have been stored"
  end

  test "a body that cannot be encoded was never sent" do
    assert %Error{reason: :invalid, status: nil} = error = Error.unencodable()
    assert Exception.message(error) =~ "nothing was sent"
  end

  test "a transport error has no status" do
    error = Error.transport(%{reason: :econnrefused})
    assert %Error{reason: :transport, status: nil, code: "transport_error"} = error
    assert Exception.message(error) == "JoobQ gateway unreachable: econnrefused"
  end

  test "a transport error names the reason's tag only, never a header value" do
    reason = {:invalid_header_value, "authorization", "Bearer s3cr3t-token"}
    error = Error.transport(%{reason: reason})
    refute Exception.message(error) =~ "s3cr3t-token"
    assert error.message == "invalid_header_value"
    assert Error.transport(:econnrefused).message == "unknown"
  end
end
